CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL, avatar TEXT, steam_id TEXT UNIQUE, steam_private INTEGER DEFAULT 0, game_count INTEGER DEFAULT 0, last_sync INTEGER, created_at INTEGER, last_login INTEGER);
CREATE TABLE IF NOT EXISTS library (user_id TEXT NOT NULL, appid INTEGER NOT NULL, minutes INTEGER DEFAULT 0, minutes_2w INTEGER DEFAULT 0, PRIMARY KEY (user_id, appid));
CREATE INDEX IF NOT EXISTS library_appid ON library(appid);
CREATE TABLE IF NOT EXISTS games (appid INTEGER PRIMARY KEY, name TEXT, is_free INTEGER DEFAULT 0, coop INTEGER DEFAULT 0, pvp INTEGER DEFAULT 0, multi INTEGER DEFAULT 0, max_players INTEGER, genres TEXT, prices TEXT, meta_at INTEGER, description TEXT, header TEXT, review_score INTEGER, review_pct INTEGER, review_count INTEGER, modded INTEGER DEFAULT 0, workshop INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS snapshots (user_id TEXT NOT NULL, day TEXT NOT NULL, minutes INTEGER, minutes_2w INTEGER, games INTEGER, PRIMARY KEY (user_id, day));
CREATE TABLE IF NOT EXISTS charts (kind TEXT NOT NULL, rank INTEGER NOT NULL, appid INTEGER NOT NULL, value INTEGER, fetched_at INTEGER, PRIMARY KEY (kind, rank));
CREATE TABLE IF NOT EXISTS pitches (id INTEGER PRIMARY KEY AUTOINCREMENT, appid INTEGER NOT NULL, by_user TEXT NOT NULL, to_users TEXT, note TEXT, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS votes (pitch_id INTEGER NOT NULL, user_id TEXT NOT NULL, PRIMARY KEY (pitch_id, user_id));
CREATE TABLE IF NOT EXISTS hidden_games (user_id TEXT NOT NULL, appid INTEGER NOT NULL, PRIMARY KEY (user_id, appid));
CREATE TABLE IF NOT EXISTS keyshop (appid INTEGER NOT NULL, cc TEXT NOT NULL, price REAL, url TEXT, fetched_at INTEGER, PRIMARY KEY (appid, cc));
CREATE TABLE IF NOT EXISTS kv (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE IF NOT EXISTS news (gid TEXT PRIMARY KEY, appid INTEGER NOT NULL, title TEXT, url TEXT, date INTEGER, patch INTEGER DEFAULT 0, snippet TEXT, feed TEXT);
